-- ChubbyLu Bakery POS v1.0.0 — Phase 18 launch readiness checks
create or replace function public.get_launch_readiness() returns jsonb language plpgsql security definer stable set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_shop_row public.shops%rowtype;v_admins int;v_products int;v_uncosted int;v_pin boolean;v_backup boolean;v_drawer boolean;v_po int;v_batches int;
begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;select * into v_shop_row from public.shops where id=v_shop;select count(*) into v_admins from public.staff_profiles where shop_id=v_shop and role='admin' and active;select count(*) into v_products from public.products where shop_id=v_shop and active;select count(*) into v_uncosted from public.products where shop_id=v_shop and active and cost_price=0;select exists(select 1 from public.staff_profiles where shop_id=v_shop and role='admin' and active and pin_hash is not null) into v_pin;select exists(select 1 from public.backup_exports where shop_id=v_shop) into v_backup;select exists(select 1 from public.cash_drawer_sessions where shop_id=v_shop and status='open') into v_drawer;select count(*) into v_po from public.purchase_orders where shop_id=v_shop and status='ordered' and expected_date<current_date;select count(*) into v_batches from public.production_batches where shop_id=v_shop and status='scheduled' and scheduled_date<current_date;
return jsonb_build_array(
jsonb_build_object('id','migrations','label','Database feature set','status','pass','detail','Phase 18 can access all required operational tables and functions.'),
jsonb_build_object('id','business','label','Business profile','status',case when nullif(trim(v_shop_row.name),'') is null then 'fail' when v_shop_row.address is null or v_shop_row.phone is null then 'warning' else 'pass' end,'detail',case when nullif(trim(v_shop_row.name),'') is null then 'Business name is required.' when v_shop_row.address is null or v_shop_row.phone is null then 'Add the business address and phone before printing production receipts.' else 'Business name, address, and phone are configured.' end),
jsonb_build_object('id','admins','label','Administrator continuity','status',case when v_admins>0 then 'pass' else 'fail' end,'detail',v_admins||' active administrator(s).'),
jsonb_build_object('id','pin','label','Manager approval PIN','status',case when v_pin then 'pass' else 'fail' end,'detail',case when v_pin then 'At least one active administrator has a manager PIN.' else 'Configure a manager PIN before refunds and voids are used.' end),
jsonb_build_object('id','products','label','Active product catalog','status',case when v_products>0 then 'pass' else 'fail' end,'detail',v_products||' active product(s).'),
jsonb_build_object('id','costs','label','Product cost coverage','status',case when v_uncosted=0 then 'pass' else 'warning' end,'detail',case when v_uncosted=0 then 'Every active product has a non-zero cost.' else v_uncosted||' active product(s) have zero cost; profitability may be overstated.' end),
jsonb_build_object('id','backup','label','Business backup','status',case when v_backup then 'pass' else 'warning' end,'detail',case when v_backup then 'At least one protected backup export has been requested.' else 'Create and securely store a backup before launch.' end),
jsonb_build_object('id','drawer','label','Cash drawer state','status',case when v_drawer then 'warning' else 'pass' end,'detail',case when v_drawer then 'A drawer is currently open; close and reconcile it before deployment maintenance.' else 'No unreconciled open drawer.' end),
jsonb_build_object('id','purchase_orders','label','Overdue purchase orders','status',case when v_po=0 then 'pass' else 'warning' end,'detail',v_po||' overdue open purchase order(s).'),
jsonb_build_object('id','production','label','Overdue production batches','status',case when v_batches=0 then 'pass' else 'warning' end,'detail',v_batches||' overdue scheduled batch(es).')
);end $$;
revoke all on function public.get_launch_readiness() from public;grant execute on function public.get_launch_readiness() to authenticated;
